(async () => {
  const url = 'https://learn.microsoft.com/en-us/cli/azure/reference-index?view=azure-cli-latest&preserve-view=true';
  const html = await (await fetch(url)).text();
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const h = doc.querySelector('#az-login');
  if (!h) return 'az-login not found';
  let section = '';
  let n = h.closest('.heading-wrapper') || h;
  // collect from this heading until next h2 heading wrapper or h2
  for (let cur = n; cur; cur = cur.nextElementSibling) {
    const txt = cur.innerText || cur.textContent || '';
    section += '\n' + txt;
    const next = cur.nextElementSibling;
    if (next && (next.querySelector?.('h2') || next.matches?.('h2'))) break;
  }
  if (section.trim().length < 50) {
    const body = doc.body.innerText;
    const i = body.indexOf('az login');
    return body.slice(Math.max(0, i - 500), i + 3000);
  }
  return section.slice(0, 5000);
})()
